def medicine_c2(text: str) -> str:
    lines = text.splitlines(keepends=True)
    out = []
    prev = None
    run = 0
    changed = False
    for line in lines:
        s = line.strip()
        if len(s) >= 20 and s == prev:
            run += 1
            if run >= 12:
                changed = True
            if run > 3:
                continue
        else:
            prev = s if len(s) >= 20 else None
            run = 1 if prev else 0
        out.append(line)
    return "".join(out) if changed else text


